    id: string;
    cardId: string;
    brandId: string;
    categoryId: string;
    amount: number;
    date: string;
    expectedBenefit: number;
    /** Rule expected to produce the benefit; omit when no benefit applies. */
    ruleId?: string;
    performance?: number;
